import subprocess, os
def run(a, env=None):
    e=dict(os.environ)
    if env:
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    r=subprocess.run(["./executable"]+a, capture_output=True, text=True, env=e)
    print(a, env, "=>", repr(r.stdout), repr(r.stderr), r.returncode)

for env in [None, {"PASTEL_COLOR_MODE":"24bit"},{"PASTEL_COLOR_MODE":"8bit"},{"PASTEL_COLOR_MODE":"off"},{"PASTEL_COLOR_MODE":"always"},{"COLORTERM":"truecolor"},{"TERM":"xterm-256color"},{"TERM":"dumb"},{"NO_COLOR":"1"},{"FORCE_COLOR":"1"},{"CLICOLOR":"0"}]:
    run(["complement","red"], env)
for mode in ["24bit","8bit","off","auto"]:
    run(["-m",mode,"complement","red"])
    run(["--color-mode",mode,"complement","red"])
    run(["-f","complement","red"])
PY"}

