import subprocess, random, math, json
random.seed(42)
cols=['%02x%02x%02x'%(random.randrange(256),random.randrange(256),random.randrange(256)) for _ in range(300)]
def get(fmt, cols):
    return subprocess.run(["./executable","format",fmt]+cols,capture_output=True,text=True).stdout.splitlines()
ansi_obs=[int(x) for x in get("ansi-8bit-value", cols)]
name_obs=get("name", cols)
names=json.load(open("/tmp/names.json"))
# canonical names: exclude aliases cyan,magenta,grey variants etc (?) keep first alphabetical per hex
canon={}
for n,h in sorted(names.items()):
    canon.setdefault(h, n)
named=[]
for h,n in canon.items():
    rgb=tuple(int(h[1+i:1+i+2],16) for i in (0,2,4))
    named.append((n,rgb))
# remove duplicates? named 139 by hex unique
print("named unique hex", len(named))
# color functions
def lin(c):
    c=c/255
    return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
def xyz(rgb):
    R,G,B=(lin(c) for c in rgb)
    return (0.4124*R+0.3576*G+0.1805*B, 0.2126*R+0.7152*G+0.0722*B, 0.0193*R+0.1192*G+0.9505*B)
def lab(rgb):
    X,Y,Z=xyz(rgb); x=X/0.95047; y=Y/1.0; z=Z/1.08883
    def f(t): return t**(1/3) if t>0.008856 else 7.787*t+16/116
    fx,fy,fz=f(x),f(y),f(z)
    return (116*fy-16,500*(fx-fy),200*(fy-fz))
def oklab(rgb):
    # via xyz wiki like discovered
    X,Y,Z=xyz(rgb)
    l=0.8189330101*X+0.3618667424*Y-0.1288597137*Z
    m=0.0329845436*X+0.9293118715*Y+0.0361456387*Z
    s=0.0482003018*X+0.2643662691*Y+0.6338517070*Z
    def cb(t): return t**(1/3) if t>=0 else -((-t)**(1/3))
    l,m,s=cb(l),cb(m),cb(s)
    return (0.2104542553*l+0.7936177850*m-0.0040720468*s,1.9779984951*l-2.4285922050*m+0.4505937099*s,0.0259040371*l+0.7827717662*m-0.8086757660*s)
def ciede2000(lab1, lab2):
    # implement standard
    L1,a1,b1=lab1; L2,a2,b2=lab2
    avg_L=(L1+L2)/2; C1=math.hypot(a1,b1); C2=math.hypot(a2,b2); avg_C=(C1+C2)/2
    avg_C7=avg_C**7; G=0.5*(1-math.sqrt(avg_C7/(avg_C7+25**7))) if avg_C>0 else 0.5
    a1p=(1+G)*a1; a2p=(1+G)*a2; C1p=math.hypot(a1p,b1); C2p=math.hypot(a2p,b2)
    def hp(ap,b):
        if ap==0 and b==0: return 0
        h=math.degrees(math.atan2(b,ap)); return h+360 if h<0 else h
    h1p=hp(a1p,b1); h2p=hp(a2p,b2)
    dLp=L2-L1; dCp=C2p-C1p
    if C1p*C2p==0: dhp=0
    else:
        dhp=h2p-h1p
        if dhp>180: dhp-=360
        elif dhp<-180: dhp+=360
    dHp=2*math.sqrt(C1p*C2p)*math.sin(math.radians(dhp)/2)
    avg_Lp=(L1+L2)/2; avg_Cp=(C1p+C2p)/2
    if C1p*C2p==0: avg_hp=h1p+h2p
    else:
        diff=abs(h1p-h2p)
        if diff<=180: avg_hp=(h1p+h2p)/2
        elif h1p+h2p<360: avg_hp=(h1p+h2p+360)/2
        else: avg_hp=(h1p+h2p-360)/2
    T=1-0.17*math.cos(math.radians(avg_hp-30))+0.24*math.cos(math.radians(2*avg_hp))+0.32*math.cos(math.radians(3*avg_hp+6))-0.20*math.cos(math.radians(4*avg_hp-63))
    d_theta=30*math.exp(-(((avg_hp-275)/25)**2))
    Rc=2*math.sqrt(avg_Cp**7/(avg_Cp**7+25**7)) if avg_Cp>0 else 0
    Sl=1+ (0.015*((avg_Lp-50)**2))/math.sqrt(20+((avg_Lp-50)**2))
    Sc=1+0.045*avg_Cp; Sh=1+0.015*avg_Cp*T
    Rt=-math.sin(math.radians(2*d_theta))*Rc
    return math.sqrt((dLp/Sl)**2+(dCp/Sc)**2+(dHp/Sh)**2+Rt*(dCp/Sc)*(dHp/Sh))

metrics={}
def euclid_rgb(a,b): return sum((x-y)**2 for x,y in zip(a,b))
def weighted_rgb(a,b):
    rm=(a[0]+b[0])/2
    return (2+rm/256)*(a[0]-b[0])**2+4*(a[1]-b[1])**2+(2+(255-rm)/256)*(a[2]-b[2])**2
def euclid_lab(a,b):
    la,lb=lab(a),lab(b); return sum((x-y)**2 for x,y in zip(la,lb))
def euclid_oklab(a,b):
    la,lb=oklab(a),oklab(b); return sum((x-y)**2 for x,y in zip(la,lb))
def de2000(a,b): return ciede2000(lab(a),lab(b))
def euclid_lin(a,b):
    la=[lin(c) for c in a]; lb=[lin(c) for c in b]; return sum((x-y)**2 for x,y in zip(la,lb))
metrics={"rgb":euclid_rgb,"wrgb":weighted_rgb,"lab":euclid_lab,"oklab":euclid_oklab,"de2000":de2000,"lin":euclid_lin}

# prepare named conversions caching by rgb in metrics functions slow but ok for evaluation subset maybe 150
palette=[]
levels=[0,95,135,175,215,255]
for r in levels:
 for g in levels:
