#!/usr/bin/env python3
import sys, os, math, re, random, subprocess

VERSION = "pastel 0.11.0"
PROG = os.path.basename(sys.argv[0]) if sys.argv and sys.argv[0] else "pastel"
# clap uses the file name (without directory). Empty argv0 fallback above.

class PastelError(Exception):
    pass

def eprint_pastel(msg):
    # Colouring of the error label is handled in main error handler where mode info is known.
