# ---------- numeric helpers (Rust-like) ----------
def rust_min(a,b):
    if math.isnan(a): return b
    if math.isnan(b): return a
    return a if a < b else b
def rust_max(a,b):
    if math.isnan(a): return b
    if math.isnan(b): return a
    return a if a > b else b
def clamp_rust(x, lo, hi):
    return rust_max(lo, rust_min(hi, x))
def round_half_away(x):
    if math.isnan(x): return 0
    if x >= 0: return int(math.floor(x+0.5))
    else: return int(math.ceil(x-0.5))
def fmt_alpha(a):
    s = f"{a:.3f}"
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    if s == "-0": s = "0"
    if s == "": s = "0"
    return s
