    # Rust f64 FromStr: accepts inf, -inf, infinity, NaN (case-insensitive), decimal with exponent,
    # rejects whitespace, underscores, empty, hex etc.
    if s is None or s == "" or s.strip() != s:
        raise ValueError(s)
    if "_" in s:
        raise ValueError(s)
    low = s.lower()
    if low in ("inf", "+inf", "infinity", "+infinity"):
        return math.inf
    if low in ("-inf", "-infinity"):
        return -math.inf
    if low in ("nan", "+nan", "-nan"):
        return math.nan
    # Python float accepts things Rust does not (e.g. '1_0' handled, also 'nan(...)' )
    if not re.fullmatch(r'[+-]?((\d+(\.\d*)?)|(\.\d+))([eE][+-]?\d+)?', s):
        raise ValueError(s)
    return float(s)
def parse_number_float(s):
    try:
        return parse_rust_float(s)
    except Exception:
        raise PastelError(f"Could not parse number '{s}'")
def parse_number_usize(s):
    # Rust usize FromStr: optional leading +, digits only, range check 0..2**64-1
    if s is None or not re.fullmatch(r'\+?\d+', s or ""):
        raise PastelError(f"Could not parse number '{s}'")
    try:
        v = int(s, 10)
    except Exception:
        raise PastelError(f"Could not parse number '{s}'")
    if v < 0 or v > 18446744073709551615:
        raise PastelError(f"Could not parse number '{s}'")
    return v

