def _norm_hue(h):
    # pastel keeps hue 360 exactly as 360, but wraps values outside [0,360]
    if h != h:  # NaN
        return h
    if 0.0 <= h <= 360.0:
        return h
    # euclidean modulo
    r = h % 360.0
    return r

class Color:
    __slots__ = ("h","s","l","a")
    def __init__(self, h, s, l, a=1.0):
        self.h = _norm_hue(float(h))
        self.s = clamp_rust(float(s), 0.0, 1.0)
        self.l = clamp_rust(float(l), 0.0, 1.0)
        self.a = clamp_rust(float(a), 0.0, 1.0)
    def copy(self):
        return Color(self.h, self.s, self.l, self.a)
    # RGB float 0..1 (from HSL)
    def to_rgb_float(self):
        h = self.h % 360.0
        s = self.s; l = self.l
        c = (1.0 - abs(2.0*l - 1.0)) * s
        x = c * (1.0 - abs((h/60.0) % 2.0 - 1.0))
        m = l - c/2.0
