        return Color(0.0, 0.0, l, a)
    delta = mx-mn
    if delta == 0:
        s = 0.0
    else:
        denom = (1.0 - abs(2.0*l-1.0))
        if denom == 0:
            s = math.inf if delta>0 else 0.0
