    else:
        sv = 2.0 * (1.0 - l/v) if v != 0 else 0.0
    return (h, sv, v)

# linearisation
def _srgb_to_linear(c):
    if c <= 0.04045:
        return c/12.92
    return ((c+0.055)/1.055)**2.4
def _linear_to_srgb(c):
    if c <= 0.0031308:
        return 12.92*c
    return 1.055*(c**(1.0/2.4)) - 0.055 if c>=0 else 12.92*c  # c>0.0031 here normally

def color_to_xyz(col):
    r,g,b = col.to_rgb_float()
    R=_srgb_to_linear(r); G=_srgb_to_linear(g); B=_srgb_to_linear(b)
    X=0.4124*R+0.3576*G+0.1805*B
    Y=0.2126*R+0.7152*G+0.0722*B
    Z=0.0193*R+0.1192*G+0.9505*B
    return (X,Y,Z)

