    # inverse sRGB matrix (wikipedia)
    Rlin= 3.2406*X -1.5372*Y -0.4986*Z
    Glin=-0.9689*X +1.8758*Y +0.0415*Z
    Blin= 0.0557*X -0.2040*Y +1.0570*Z
    r=_linear_to_srgb(Rlin); g=_linear_to_srgb(Glin); b=_linear_to_srgb(Blin)
    return color_from_rgb_float(r,g,b,a)

_EPS=0.008856
_KAPPA=903.3
_WX=0.95047; _WY=1.0; _WZ=1.08883
def _lab_f(t):
    if t > _EPS:
        return t**(1.0/3.0)
    return 7.787*t + 16.0/116.0
def xyz_to_lab(X,Y,Z):
    fx=_lab_f(X/_WX); fy=_lab_f(Y/_WY); fz=_lab_f(Z/_WZ)
    L=116.0*fy-16.0; A=500.0*(fx-fy); B=200.0*(fy-fz)
    return (L,A,B)
def lab_to_xyz(L,A,B):
    fy=(L+16.0)/116.0; fx=fy+A/500.0; fz=fy-B/200.0
    def inv_cube(f):
        cube=f**3
        if cube>_EPS:
            return cube
        return (116.0*f-16.0)/_KAPPA
    xr=inv_cube(fx)
    if L>_KAPPA*_EPS:
        yr=((L+16.0)/116.0)**3
    else:
        yr=L/_KAPPA
    zr=inv_cube(fz)
    return (xr*_WX, yr*_WY, zr*_WZ)

def color_to_lab(col):
    return xyz_to_lab(*color_to_xyz(col))
def color_from_lab(L,A,B,a=1.0):
    X,Y,Z=lab_to_xyz(L,A,B)
    return color_from_xyz(X,Y,Z,a)
