    C=math.hypot(A,B); H=math.degrees(math.atan2(B,A))%360.0
    return (L,C,H)
def color_to_lch(col):
    L,A,B=color_to_lab(col); return lab_to_lch(L,A,B)
def color_from_lch(L,C,H,a=1.0):
    rad=math.radians(H); A=C*math.cos(rad); B=C*math.sin(rad)
    return color_from_lab(L,A,B,a)

