# ---------- Parsing ----------
_NUMBER_RE = r'[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?|[+-]?(?:inf|infinity|nan)'
def _parse_float_token(tok):
    # returns float or None
    try:
        return parse_rust_float(tok)
    except Exception:
        return None

def _parse_hue_token(tok):
    # hue: number optionally followed by deg, °, turn, grad, rad (lowercase, no space before suffix inside token)
    factors=(("turn",360.0),("grad",0.9),("deg",1.0),("rad",180.0/math.pi),("°",1.0))
    for suf,fac in factors:
        if tok.endswith(suf):
            num=_parse_float_token(tok[:-len(suf)])
            if num is None: return None
            return num*fac
    return _parse_float_token(tok)

def _split_components(inner):
    # components are separated by commas and/or whitespace (space/tab). Empty components -> invalid
    if inner.strip()=="":
        return None
    # detect leading/trailing separators or double commas (comma separated empties)
    # We use a tokenizer: split by commas first, then each piece split by whitespace
    parts=[]
    # Reject sequences that produce empty tokens, except whitespace splitting
    # Split using regex on commas/space/tab but detect ',,' and leading/trailing comma
    s=inner.strip()
    if s.startswith(",") or s.endswith(","):
        return None
    if ",," in re.sub(r'\s', '', s):
        return None
    # tokenise: separators are commas, spaces, tabs (not newlines per original)
    if "\n" in inner or "\r" in inner:
        return None
    tokens=re.split(r'[\s,]+', s.strip())
    # re.split on a trimmed string: leading/trailing not empty
    tokens=[t for t in tokens if t!=""] if False else tokens
    # Actually the above pattern will fail for "255,,0" because tokens will skip empty; detect that via raw
    if re.search(r',\s*,', inner):
        return None
    return tokens

def _parse_alpha_token(tok):
    if tok is None: return None
    if tok.endswith("%"):
        num=_parse_float_token(tok[:-1])
        if num is None: return None
        return num/100.0
    return _parse_float_token(tok)

def _parse_percent_token(tok):
    # must end with %
    if tok is None or not tok.endswith("%"):
        return None
    return _parse_float_token(tok[:-1])

def _make_rgb_from_tokens(tokens):
    # tokens 3 or 4; first three either all numbers or all percentages; alpha optional
    if tokens is None or len(tokens) not in (3,4):
        return None
    first=tokens[:3]
    percent_flags=[t.endswith("%") for t in first]
    if any(percent_flags) and not all(percent_flags):
        return None
    vals=[]
    for t,is_pct in zip(first, percent_flags):
        if is_pct:
            num=_parse_float_token(t[:-1])
            if num is None: return None
            v=num/100.0*255.0
        else:
            num=_parse_float_token(t)
            if num is None: return None
            v=num
        # round to nearest, clamp 0-255 (Rust round+cast saturating)
        if math.isnan(v):
            vi=0
        elif math.isinf(v):
            vi=255 if v>0 else 0
        else:
            vi=clamp_rust(round_half_away(v),0,255)
        vals.append(vi)
    a=1.0
    if len(tokens)==4:
        a=_parse_alpha_token(tokens[3])
        if a is None: return None
    return color_from_rgb_u8(vals[0],vals[1],vals[2],a)

