            h=_parse_hue_token(tokens[0]); sat=_parse_percent_token(tokens[1]); val=_parse_percent_token(tokens[2])
            if h is None or sat is None or val is None: return None
            a=1.0
            if len(tokens)==4:
                a=_parse_alpha_token(tokens[3]);
                if a is None: return None
            return color_from_hsv(h, sat/100.0, val/100.0, a)
    # gray
    if s.startswith("gray(") and s.endswith(")"):
        inner=s[5:-1]; tokens=_split_components(inner)
        if tokens is None or len(tokens)!=1: return None
        tok=tokens[0]
        # gray special: negative plain numbers are rejected by original (but %? and exponent works)
        # Implementation observed: gray(-0.5) invalid, gray(NaN) invalid, gray(inf) valid.
        # We emulate: token must not start with '-' unless it is -inf? Original rejected -1; test -inf in gray probably parser?
        # Simplify: reject tokens that parse to NaN, reject leading '-' for finite numbers.
        if tok.endswith("%"):
            num=_parse_float_token(tok[:-1])
            if num is None or math.isnan(num): return None
            if num < 0 and math.isfinite(num): # '%' negative? original may reject? keep allowing? gray(-?) tested only plain; be permissive
                pass
            return Color(0.0,0.0,num/100.0,1.0)
        else:
            # reject negative signs (original rejects gray(-0.5))
            if tok.startswith("-") and tok.lower() not in ("-inf","-infinity"):
                return None
            num=_parse_float_token(tok)
            if num is None or math.isnan(num): return None
            return Color(0.0,0.0,num,1.0)
    # lab family case-insensitive
    low=s.lower()
    for pref, kind in (("oklch","oklch"),("oklab","oklab"),("lch","lch"),("lab","lab")):
        if low.startswith(pref+"(") and s.endswith(")"):
            inner=s[len(pref)+1:-1]; tokens=_split_components(inner)
            if tokens is None or len(tokens) not in (3,4): return None
            a=1.0
            if len(tokens)==4:
                a=_parse_alpha_token(tokens[3]);
                if a is None: return None
            if kind=="lab":
                L=_parse_float_token(tokens[0]); A=_parse_float_token(tokens[1]); B=_parse_float_token(tokens[2])
                if None in (L,A,B): return None
                return color_from_lab(L,A,B,a)
            if kind=="lch":
                L=_parse_float_token(tokens[0]); C=_parse_float_token(tokens[1]); H=_parse_hue_token(tokens[2])
                if None in (L,C,H): return None
                return color_from_lch(L,C,H,a)
            if kind=="oklab":
                L=_parse_float_token(tokens[0]); A=_parse_float_token(tokens[1]); B=_parse_float_token(tokens[2])
                if None in (L,A,B): return None
                return color_from_oklab(L,A,B,a)
            if kind=="oklch":
                L=_parse_float_token(tokens[0]); C=_parse_float_token(tokens[1]); H=_parse_hue_token(tokens[2])
                if None in (L,C,H): return None
                return color_from_oklch(L,C,H,a)
    # bare rgb triplet: numbers/space/comma separated, 3 or 4 tokens
    # Only attempt if the string looks like it starts with a digit / + - . and contains separators
    if re.match(r'^[+-]?[\d.]', s):
        tokens=_split_components(s)
        if tokens is not None and len(tokens) in (3,4):
            col=_make_rgb_from_tokens(tokens)
            if col is not None:
                return col
    return None

def parse_color_or_error(display):
    col=parse_color(display)
    if col is None:
        raise PastelError(f"Could not parse color '{display}'")
    return col

