# ---------- stdin ----------
_stdin_buf=None
def stdin_buffer():
    global _stdin_buf
    if _stdin_buf is None:
        _stdin_buf=sys.stdin.buffer
    return _stdin_buf
def stdin_read_line():
    try:
        line=stdin_buffer().readline()
    except Exception:
        return None
    if line==b"" or line=='':
        return None
    if isinstance(line, bytes):
        text=line.decode('utf-8', errors='replace')
    else:
        text=line
    # Rust lines(): strip trailing \n and \r\n
    if text.endswith("\n"): text=text[:-1]
    if text.endswith("\r"): text=text[:-1]
    return text
def stdin_read_rest():
    try:
        data=stdin_buffer().read()
    except Exception:
        return ""
    if isinstance(data, bytes):
        return data.decode('utf-8', errors='replace')
    return data

