def show_spectrum():
    if CFG.spectrum_shown:
        return
    CFG.spectrum_shown=True
    # plain version (stderr not a tty, or mode off) matches captured output
    if not CFG.stderr_is_tty or CFG.paint_mode=="off":
        sys.stderr.write(" "*52+"\n")
        for _ in range(25):
            sys.stderr.write("   "+"▀"*48+" \n")
        sys.stderr.write("\n")
        return
    # coloured approximation: gradient spectrum with border cells
    # Pixel grid: 48 columns, 50 rows. y: combine white/black start then gradient from dark to light
    # We generate colours in HSL: hue across, lightness down rows (row sequence approx)
    def rgb_from_hsl(h,s,l):
        return Color(h,s,l,1.0).to_rgb_u8()
    sys.stderr.write(" "*52+"\n")
    for text_row in range(25):
        line="  "
        # border white cell
        line+=paint_cell(" ", (255,255,255),(255,255,255), CFG.paint_mode)
        for x in range(48):
            # two sub-rows
            def pix_color(px, py):
