# ---------- operations ----------
def interpolate_hue(h1,h2,t):
    diff=h2-h1
    # shortest path using modulo on raw hues (hues may be 360)
    # normalize diff to [-180,180]
    while diff>180.0: diff-=360.0
    while diff<-180.0: diff+=360.0
    return h1+diff*t

def interpolate_color(c1,c2,t,space):
    # t=0 -> c1, t=1 -> c2
    a_alpha=c1.a+(c2.a-c1.a)*t
    space_norm=space.lower() if isinstance(space,str) else space
    if space_norm=="rgb":
        r1,g1,b1=c1.to_rgb_u8(); r2,g2,b2=c2.to_rgb_u8()
        r=clamp_rust(round_half_away(r1+(r2-r1)*t),0,255); g=clamp_rust(round_half_away(g1+(g2-g1)*t),0,255); b=clamp_rust(round_half_away(b1+(b2-b1)*t),0,255)
        return color_from_rgb_u8(r,g,b,a_alpha)
    if space_norm=="hsl":
        h=interpolate_hue(c1.h,c2.h,t); s=c1.s+(c2.s-c1.s)*t; l=c1.l+(c2.l-c1.l)*t
        return Color(h,s,l,a_alpha)
    if space_norm=="lab":
        L1,A1,B1=color_to_lab(c1); L2,A2,B2=color_to_lab(c2)
        return color_from_lab(L1+(L2-L1)*t, A1+(A2-A1)*t, B1+(B2-B1)*t, a_alpha)
    if space_norm=="lch":
        L1,C1,H1=color_to_lch(c1); L2,C2,H2=color_to_lch(c2)
        h=interpolate_hue(H1,H2,t)
        return color_from_lch(L1+(L2-L1)*t, C1+(C2-C1)*t, h, a_alpha)
    if space_norm=="oklab":
        L1,A1,B1=color_to_oklab(c1); L2,A2,B2=color_to_oklab(c2)
        return color_from_oklab(L1+(L2-L1)*t, A1+(A2-A1)*t, B1+(B2-B1)*t, a_alpha)
    return c1

def sort_value(col, order):
    if order=="brightness": return color_brightness(col)
    if order=="luminance": return color_luminance(col)
    if order=="hue": return color_to_lch(col)[2]
    if order=="chroma": return color_to_lch(col)[1]
    return 0.0

def sort_colors(colors, order, reverse=False, unique=False):
    if unique:
        seen=set(); uniq=[]
        for c in colors:
            key=c.to_rgb_u8()
            if key not in seen:
                seen.add(key); uniq.append(c)
        colors=uniq
    else:
        colors=list(colors)
    if order=="random":
        random.shuffle(colors)
    else:
        colors.sort(key=lambda c: int(sort_value(c,order)*1000.0))
    if reverse:
        colors.reverse()
    return colors

def apply_set_property(col, prop, value):
    if prop=="lightness":
        L,C,H=color_to_lch(col); return color_from_lch(value,C,H,col.a)
    if prop=="hue":
        L,C,H=color_to_lch(col); return color_from_lch(L,C,value,col.a)
    if prop=="chroma":
        L,C,H=color_to_lch(col); return color_from_lch(L,value,H,col.a)
    if prop=="lab-a":
        L,A,B=color_to_lab(col); return color_from_lab(L,value,B,col.a)
    if prop=="lab-b":
        L,A,B=color_to_lab(col); return color_from_lab(L,A,value,col.a)
    if prop=="oklab-l":
        L,A,B=color_to_oklab(col); return color_from_oklab(value,A,B,col.a)
    if prop=="oklab-a":
        L,A,B=color_to_oklab(col); return color_from_oklab(L,value,B,col.a)
    if prop=="oklab-b":
        L,A,B=color_to_oklab(col); return color_from_oklab(L,A,value,col.a)
    if prop in ("red","green","blue"):
        r,g,b=col.to_rgb_u8()
        # Rust: value as u8 (truncate toward zero, saturate)
        if math.isnan(value): vi=0
        elif value>=255: vi=255
        elif value<=0: vi=0
        else: vi=int(value)  # trunc toward zero for positive
        if prop=="red": r=vi
        elif prop=="green": g=vi
        else: b=vi
        return color_from_rgb_u8(r,g,b,col.a)
    if prop=="hsl-hue":
