        if opt.get("short"): short_map[opt["short"]]=key
    while i < len(args):
        token=args[i]
        if not after_dd and token=="--":
            after_dd=True; i+=1; continue
        if not after_dd and token=="--help":
            validate_collected_enums(cmd, pos, opts)
            raise ProgramExit(0, help_text_for(cmd, True), "")
        if not after_dd and token=="-h":
            validate_collected_enums(cmd, pos, opts)
            raise ProgramExit(0, help_text_for(cmd, False), "")
        if not after_dd and token.startswith("--") and token!="--":
            body=token[2:]
            if "=" in body:
                name, inline = body.split("=",1); has_inline=True
            else:
                name=body; inline=None; has_inline=False
            if name=="help":
                validate_collected_enums(cmd, pos, opts)
                raise ProgramExit(0, help_text_for(cmd, True), "")
            if name not in long_map:
                unexpected_argument("--"+name, cmd)
            key=long_map[name]; opt=spec["opts"][key]
            arg_display=f"--{opt['long']} <{opt.get('metavar','value')}>" if not opt.get("flag") else f"--{opt['long']}"
            if opt.get("flag"):
                if has_inline:
