            if has_inline:
                if inline=="" and opt.get("values") is not None:
                    missing_value_error(arg_display, opt.get("values"))
                opts[key]=inline; i+=1; continue
            # need next token
            if i+1>=len(args):
                missing_value_error(arg_display, opt.get("values"))
            nxt=args[i+1]
            if nxt=="-":
                opts[key]=nxt; i+=2; continue
            if nxt.startswith("-") and nxt!="-":
                # decide known option vs unknown
                # determine candidate option token display
                if nxt.startswith("--"):
                    disp="--"+nxt[2:].split("=",1)[0]
                    known = disp[2:] in long_map or disp[2:] in ("help",)
                else:
                    disp="-"+nxt[1]
                    known = nxt[1] in short_map or nxt[1]=="h"
                if known:
