                    continue
                # value option
                arg_display=f"--{opt['long']} <{opt.get('metavar','value')}>"
                rest=chars[j+1:]
                if rest!="":
                    if rest.startswith("="):
                        val=rest[1:]
                        if val=="" and opt.get("values") is not None:
                            missing_value_error(arg_display, opt.get("values"))
                        opts[key]=val
                    else:
                        opts[key]=rest
                    consumed_value=True; break
                else:
                    if i+1>=len(args):
                        missing_value_error(arg_display, opt.get("values"))
                    nxt=args[i+1]
                    if nxt=="-":
                        opts[key]=nxt; i+=1; consumed_value=True; break
                    if nxt.startswith("-") and nxt!="-":
                        if nxt.startswith("--"):
                            disp="--"+nxt[2:].split("=",1)[0]; known=disp[2:] in long_map or disp[2:] in ("help",)
                        else:
