            i+=1; continue
        # positional
        if spec["max_pos"] is not None and len(pos) >= spec["max_pos"]:
            # unexpected argument (no tip)
            raise_clap_stderr(f"error: unexpected argument '{token}' found\n\nUsage: {usage_str(cmd)}\n\nFor more information, try '--help'.\n")
        pos.append(token); i+=1
    return pos, opts

