    labs=[lab_of_rgb_u8(rgb) for rgb in rgbs]
    movable=[i for i in range(count) if i not in fixed_set]
    if not movable:
        if verbose: print_distinct_matrix([color_from_rgb_u8(*rgb) for rgb in rgbs], metric)
        return [color_from_rgb_u8(*rgb) for rgb in rgbs]
