            for j in range(len(labs_list)):
                if i==j: continue
                d=distance_lab(labs_list[i],labs_list[j],metric)
                if best is None or d<best: best=d
                if dmin is None or d<dmin: dmin=d
            nearest.append(best if best is not None else 0.0)
        dmean=sum(nearest)/len(nearest) if nearest else 0.0
        return dmean, (dmin if dmin is not None else 0.0)
