        dmean,dmin=stats_from_labs(labs_list)
        hexes="".join(f"{rgb[0]:02x}{rgb[1]:02x}{rgb[2]:02x} " for rgb in rgbs)
        sys.stderr.write(f"[{iteration:10d}] D_mean = {dmean:<6.2f}; D_min = {dmin:<6.2f}; T = {T:.6f} {hexes}\n")
    # phase parameters: (iterations, T0, decay per iter)
