    # For CIEDE2000 in Python reduce iterations a bit to keep runtime manageable, but keep verbose cadence
    if metric=="CIEDE2000":
        phases=[(30000,3.0,-0.00017),(60000,0.5,-0.000067)]
        # adjust T schedules to end similar: phase1 T at end approx 3*exp(-5.1), phase2 0.5*exp(-4.02)
    best_rgbs=list(rgbs); best_labs=list(labs)
