    cur_mean, cur_min = stats_from_labs(labs)
    cur_score=cur_mean
    best_score=cur_score
    for phase_idx,(iterations,T0,decay) in enumerate(phases):
        if phase_idx==1:
            # second phase starts from best found so far
            rgbs=list(best_rgbs); labs=list(best_labs); cur_mean,cur_min=stats_from_labs(labs); cur_score=cur_mean
        for it in range(iterations):
            T=T0*math.exp(decay*it)
            if verbose and it%5000==0:
                verbose_line(it,labs,T)
            if not movable: break
            k=random.choice(movable)
            cand_rgb=(random.randrange(256), random.randrange(256), random.randrange(256))
            cand_lab=lab_of_rgb_u8(cand_rgb)
            old_rgb=rgbs[k]; old_lab=labs[k]
            labs[k]=cand_lab; rgbs[k]=cand_rgb
            new_mean,new_min=stats_from_labs(labs)
            new_score=new_mean
            delta=new_score-cur_score
            if delta>=0 or (T>0 and random.random() < math.exp(delta/T) if delta/T>-700 else False):
                cur_score=new_score; cur_mean,cur_min=new_mean,new_min
                if cur_score>best_score:
                    best_score=cur_score; best_rgbs=list(rgbs); best_labs=list(labs)
            else:
