def colorcheck_text():
    panels=[(73,39,50),(16,51,30),(29,54,90)]
    def panel_line(mode):
        line="  "
        for idx,rgb in enumerate(panels):
            for _ in range(8):
                line+=paint_cell(" ", rgb, rgb, mode)
            if idx<2: line+="  "
        return line
    out="\n8-bit mode:\n"
    out+=" "*30+"\n"
    for _ in range(4): out+=panel_line("8bit")+"\n"
    out+=" "*30+"\n"
    out+="24-bit mode:\n"
    out+=" "*30+"\n"
    for _ in range(4): out+=panel_line("24bit")+"\n"
    out+=" "*30+"\n"
    out+="If your terminal emulator supports 24-bit colors, you should see three square color panels in the lower row and the colors should look similar (but slightly different from) the colors in the top row panels.\n"
    out+="The panels in the lower row should look like squares that are filled with a uniform color (no stripes or other artifacts).\n"
    out+="\n"
    out+="You can also open https://github.com/sharkdp/pastel/blob/master/doc/colorcheck.md in a browser to compare how the output should look like.\n"
    return out

