    except ProgramExit as e:
        if e.stdout: sys.stdout.write(e.stdout)
        if e.stderr: sys.stderr.write(e.stderr)
        return e.code
    except PastelError as e:
        msg=str(e)
        # style error label if stdout is a tty and styling is enabled (approximation of original)
        label="[pastel error]"
        styled=False
        if CFG.stdout_is_tty and not msg.startswith("Unknown PASTEL_COLOR_MODE"):
            if "NO_COLOR" in os.environ:
                styled=False
            else:
                env_mode=os.environ.get("PASTEL_COLOR_MODE")
                if env_mode=="off":
                    styled=False
                elif env_mode=="24bit":
                    label="\x1b[38;2;255;0;0m[pastel error]\x1b[0m"; styled=True
                elif env_mode is not None and env_mode not in ("8bit",):
                    # invalid env mode: original prints the unknown-mode error plainly; other errors would not happen
                    styled=False
                elif os.environ.get("COLORTERM") in ("truecolor","24bit"):
                    label="\x1b[38;2;255;0;0m[pastel error]\x1b[0m"; styled=True
                else:
                    # check effective explicit mode? original uses env-based detection for the label
                    label="\x1b[38;5;196m[pastel error]\x1b[0m"; styled=True
        sys.stderr.write(f"{label}: {msg}\n")
        return 1
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        return 1

