import subprocess, random, math, sys
sys.path.insert(0,'.')
import pastel as p
random.seed(123)
cols=['%02x%02x%02x'%(random.randrange(256),random.randrange(256),random.randrange(256)) for _ in range(100)]
outs=subprocess.run(["./executable","to-gray"]+cols,capture_output=True,text=True).stdout.splitlines()
def get_light(s):
    # hsl(H,0.0%,L%)
    import re; return float(re.search(r',0\.0%,([\d.]+)%\)',s).group(1))
obs=[get_light(o) for o in outs]
def candidate(colhex, mode):
    col=p.parse_color(colhex)
    if mode=="continuous":
        return p._linear_to_srgb(p.color_luminance(col))*100
    if mode=="u8_encode":
        y=p.color_luminance(col); v=p._linear_to_srgb(y); return round(v*255)/255*100
    if mode=="via_lab":
        L=p.color_to_lab(col)[0]; grey=p.color_from_lab(L,0,0); return grey.l*100
    if mode=="via_lab_rgbmax":
        L=p.color_to_lab(col)[0]; grey=p.color_from_lab(L,0,0); r,g,b=grey.to_rgb_float(); return (max(r,g,b)+min(r,g,b))/2*100
    if mode=="luminance_simple255":
        return p.color_luminance(col)*100
    if mode=="brightness_enc":
        return p._linear_to_srgb(p.color_brightness(col))*100
for mode in ["continuous","u8_encode","via_lab","via_lab_rgbmax"]:
    diffs=[abs(candidate(c,mode)-o) for c,o in zip(cols,obs)]
    exact=sum(1 for d in diffs if d<0.051)
    print(mode, "exact-ish",exact, "maxdiff",max(diffs), "meandiff",sum(diffs)/len(diffs))
    for c,o in list(zip(cols,obs))[:5]: print(c,o,candidate(c,mode))
