                    for delta in (step,-step):
                        if i==j and W[i][j]+delta<=0.05: continue
                        cand=[row[:] for row in W]; cand[i][j]+=delta; cand[j][i]=cand[i][j]
                        val=evaluate(cand)
                        if val>best:
                            W=cand; best=val; improved=True
        print(mode," step done best",best,"W",W)
    print(mode,"final",best,W)
