        elif mode=="rgb": f=tuple(x/255 for x in rgb)
        elif mode=="lch": 
            L,C,H=p.color_to_lch(c); f=(L,C*math.cos(math.radians(H)),C*math.sin(math.radians(H)))
        targets.append(f)
