import subprocess, random, math, sys
sys.path.insert(0,'.')
import pastel as p
random.seed(42)
cols=['%02x%02x%02x'%(random.randrange(256),random.randrange(256),random.randrange(256)) for _ in range(200)]
obs=[int(x) for x in subprocess.run(["./executable","format","ansi-8bit-value"]+cols,capture_output=True,text=True).stdout.splitlines()]
levels=[0,95,135,175,215,255]
def cube_candidate(rgb, quant):
    idxs=[]
    for v in rgb:
        if quant=="rgb_nearest": idx=min(range(6), key=lambda i: abs(levels[i]-v))
        elif quant=="tmux": idx=0 if v<48 else 1 if v<115 else (v-35)//40
        elif quant=="round5": idx=int(round(v/255*5))
        idxs.append(idx)
    rgb_c=tuple(levels[i] for i in idxs); code=16+36*idxs[0]+6*idxs[1]+idxs[2]
    return code, rgb_c

def gray_candidate(rgb, mode):
    if mode=="avg": gv=(rgb[0]+rgb[1]+rgb[2])//3
    elif mode=="lightness": gv=(max(rgb)+min(rgb))//2
    elif mode=="luminance": gv=int(round(p.color_brightness(p.color_from_rgb_u8(*rgb))*255))
    else: gv=rgb[0]
    # nearest grey level
    gi=min(range(23), key=lambda i: abs(8+10*i-gv))  # up to 254 (i 0..22)
    return 232+gi, (8+10*gi,)*3

def evaluate(quant, graymode, decision):
    correct=0
    for col,o in zip(cols,obs):
        rgb=tuple(int(col[i:i+2],16) for i in (0,2,4)); ccode,crgb=cube_candidate(rgb,quant); gcode,grgb=gray_candidate(rgb,graymode)
        # choose
        if decision=="rgb":
            dc=sum((a-b)**2 for a,b in zip(rgb,crgb)); dg=sum((a-b)**2 for a,b in zip(rgb,grgb)); code=ccode if dc<=dg else gcode
        elif decision=="de":
            lab=p.color_to_lab(p.color_from_rgb_u8(*rgb)); dc=p.ciede2000(lab,p.color_to_lab(p.color_from_rgb_u8(*crgb))); dg=p.ciede2000(lab,p.color_to_lab(p.color_from_rgb_u8(*grgb))); code=ccode if dc<=dg else gcode
        elif decision=="cie76":
            lab=p.color_to_lab(p.color_from_rgb_u8(*rgb)); dc=p.lab_distance_cie76(lab,p.color_to_lab(p.color_from_rgb_u8(*crgb))); dg=p.lab_distance_cie76(lab,p.color_to_lab(p.color_from_rgb_u8(*grgb))); code=ccode if dc<=dg else gcode
        elif decision=="ok":
            ok=p.color_to_oklab(p.color_from_rgb_u8(*rgb)); dc=math.dist(ok,p.color_to_oklab(p.color_from_rgb_u8(*crgb))); dg=math.dist(ok,p.color_to_oklab(p.color_from_rgb_u8(*grgb))); code=ccode if dc<=dg else gcode
        if code==o: correct+=1
    print(quant,graymode,decision,correct)
for quant in ["rgb_nearest","tmux","round5"]:
 for graymode in ["avg","lightness"]:
  for dec in ["rgb","de","cie76","ok"]:
    evaluate(quant,graymode,dec)
